const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  var somalia = ee.Geometry.Polygon([
    [[40.981, 11.987], [51.412, 11.987], [51.412, -1.659], [40.981, -1.659], [40.981, 11.987]]
  ]);

  var april2019 = ee.DateRange('2019-04-01', '2019-04-30');
  var baselineRange = ee.DateRange('2015-04-01', '2018-04-30');

  // 2. Data Acquisition - SMAP Soil Moisture
  var smap2019 = ee.ImageCollection('NASA/SMAP/SPL4SMGP/007')
    .filterBounds(somalia)
    .filterDate(april2019)
    .select('sm_surface');

  var smapBaseline = ee.ImageCollection('NASA/SMAP/SPL4SMGP/007')
    .filterBounds(somalia)
    .filterDate(baselineRange)
    .filter(ee.Filter.calendarRange(4, 4, 'month'))
    .select('sm_surface');

  // Check collection sizes
  var count2019 = smap2019.size().getInfo();
  var countBaseline = smapBaseline.size().getInfo();

  print(`2019 April Images: ${count2019}`);
  print(`Baseline April Images: ${countBaseline}`);

  if (count2019 === 0 || countBaseline === 0) {
    print("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate means
  var mean2019 = smap2019.mean();
  var meanBaseline = smapBaseline.mean();

  // Check valid pixels
  var count2019Pixels = mean2019.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: somalia,
    scale: 30000,
    maxPixels: 1e9
  }).get('sm_surface').getInfo();

  var countBaselinePixels = meanBaseline.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: somalia,
    scale: 30000,
    maxPixels: 1e9
  }).get('sm_surface').getInfo();

  print(`2019 Valid Pixels: ${count2019Pixels}`);
  print(`Baseline Valid Pixels: ${countBaselinePixels}`);

  if (count2019Pixels === 0 || countBaselinePixels === 0) {
    print("<answer>C2</answer>");
    return;
  }

  // 4. Calculation
  var soilMoisture2019 = mean2019.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: somalia,
    scale: 30000,
    maxPixels: 1e9
  }).get('sm_surface').getInfo();

  var soilMoistureBaseline = meanBaseline.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: somalia,
    scale: 30000,
    maxPixels: 1e9
  }).get('sm_surface').getInfo();

  // 5. Validation & Final Answer
  print(`Soil Moisture 2019: ${soilMoisture2019.toFixed(4)}`);
  print(`Soil Moisture Baseline: ${soilMoistureBaseline.toFixed(4)}`);

  if (soilMoisture2019 === null || soilMoistureBaseline === null || 
      isNaN(soilMoisture2019) || isNaN(soilMoistureBaseline) ||
      soilMoisture2019 < 0 || soilMoisture2019 > 0.6 ||
      soilMoistureBaseline < 0 || soilMoistureBaseline > 0.6) {
    print("<answer>C3</answer>");
  } else if (soilMoisture2019 < soilMoistureBaseline) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
